				vertex.y = radius.y - (1.0f - sinf(angleY)) * bevel;
			else
				vertex.y = (sinf(angleY) + 1.0f) * bevel - radius.y;
			vertex.z = (radius.z - (1.0f - cosf(angleY)) * bevel) * cosf(angleX);
			normal.x = cosf(angleY) * sinf(angleX);
			normal.y = sinf(angleY);
